//! Runtime support for the argument parsers generated by `arguments!`.
//! Each argument's rule is a constant, so checking a macro call's
//! arguments allocates nothing.
use super::{
    expander::ExpansionError,
    parser::ParseNode,
};

/// Kind of node an argument must be.
///     Number ⊆ Literal;
///     String ⊆ Literal;
///     Symbol ⊆ Symbolic;
///     Number ⊆ Symbolic;
///     Symbolic ⊆ Literal;
///     * ⊆ Any.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum ArgType {
    Literal,
    String,
    Symbol,
    Number,
    Symbolic,
    List,
    Any,
}

impl ArgType {
    #[must_use]
    pub fn name(self) -> &'static str {
        match self {
            Self::Literal => "literal",
            Self::String => "string",
            Self::Symbol => "symbol",
            Self::Number => "number",
            Self::Symbolic => "symbolic",
            Self::List => "list",
            Self::Any => "any",
        }
    }

    /// The type with the given name, as written in a schema or annotation.
    #[must_use]
    pub fn from_name(name: &str) -> Option<Self> {
        Some(match name {
            "literal" => Self::Literal,
            "string" => Self::String,
            "symbol" => Self::Symbol,
            "number" => Self::Number,
            "symbolic" => Self::Symbolic,
            "list" => Self::List,
            "any" => Self::Any,
            _ => return None,
        })
    }

    /// Whether a node is of this kind.
    #[must_use]
    pub fn admits(self, node: &ParseNode) -> bool {
        match node {
            ParseNode::Symbol(..) => matches!(self, Self::Literal | Self::Symbol | Self::Symbolic | Self::Any),
            ParseNode::Number(..) => matches!(self, Self::Literal | Self::Number | Self::Symbolic | Self::Any),
            ParseNode::String(..)
          | ParseNode::Raw(..) => matches!(self, Self::Literal | Self::String | Self::Any),
            ParseNode::List { .. } => matches!(self, Self::List | Self::Any),
            ParseNode::Attribute { .. } => self == Self::Any,
        }
    }
}

/// A predicate an argument must satisfy beyond its type.
pub type Predicate = for<'t> fn(&ParseNode<'t>) -> Result<(), ExpansionError<'t>>;

/// What an argument must be: its type, optionally one of a set
/// of exact values, and optionally satisfying a predicate.
#[derive(Debug, Clone, Copy)]
pub struct ArgRule {
    pub kind: ArgType,
    pub one_of: &'static [&'static str],
    pub satisfying: Option<Predicate>,
}

impl ArgRule {
    pub fn check<'a>(&self, node: &ParseNode<'a>) -> Result<(), ExpansionError<'a>> {
        if !self.kind.admits(node) {
            return Err(match node {
                ParseNode::Attribute { keyword, .. } => unexpected_named(node, keyword),
                _ => ExpansionError(
                    format!("Expected a {} node, got a {} instead.", self.kind.name(), node.node_type()),
                    node.owned_site()),
            });
        }
        if !self.one_of.is_empty() {
            let value = node.atomic().map(|atom| atom.value.as_ref());
            if !value.is_some_and(|value| self.one_of.contains(&value)) {
                let options: Vec<String> = self.one_of.iter().map(|option| format!("`{option}'")).collect();
                return Err(ExpansionError(
                    format!("This argument's value must be one of: {}.", options.join(", ")),
                    node.owned_site()));
            }
        }
        match self.satisfying {
            Some(predicate) => predicate(node),
            None => Ok(()),
        }
    }
}

#[must_use]
pub fn unexpected_positional<'a>(param: &ParseNode<'a>, position: usize) -> ExpansionError<'a> {
    ExpansionError(
        format!("Unexpected positional argument in position {position}."),
        param.owned_site())
}

#[must_use]
pub fn unexpected_named<'a>(param: &ParseNode<'a>, keyword: &str) -> ExpansionError<'a> {
    ExpansionError(
        format!("Unexpected named argument `:{keyword}'."),
        param.owned_site())
}

#[must_use]
pub fn repeated_named<'a>(param: &ParseNode<'a>, keyword: &str) -> ExpansionError<'a> {
    ExpansionError(
        format!("Named argument `:{keyword}' is given more than once."),
        param.owned_site())
}

/// A mandatory argument is missing, reported at the end of the call's arguments.
#[must_use]
pub fn missing_positional<'a>(node: &ParseNode<'a>, params: &[ParseNode<'a>], position: usize) -> ExpansionError<'a> {
    let site = params.last().map_or_else(|| node.owned_site(), ParseNode::owned_site);
    ExpansionError(format!("Missing argument in position {position}."), site)
}

#[must_use]
pub fn missing_named<'a>(node: &ParseNode<'a>, params: &[ParseNode<'a>], keyword: &str) -> ExpansionError<'a> {
    let site = params.last().map_or_else(|| node.owned_site(), ParseNode::owned_site);
    ExpansionError(format!("Missing named argument `:{keyword}'."), site)
}
